refentry.refsect1:
&reftitle.description;
public mixedPDOStatement::fetch intmodePDO::FETCH_DEFAULT intcursorOrientationPDO::FETCH_ORI_NEXT intcursorOffset0
Recupera una línea de un conjunto de resultados asociado a una instancia de PDOStatement. El argumento mode determina la forma en que PDO devuelve la línea.

&reftitle.returnvalues;

 El valor devuelto por esta función en caso de éxito depende del tipo de recuperación.
 En todos los casos, se devuelve &false; si ocurre un error o si no hay más líneas.

  &reftitle.examples;

   Recuperación de líneas utilizando diferentes estilos de recuperación


<?php
$db = new PDO('sqlite::memory:');
$db->exec("CREATE TABLE fruit (name VARCHAR(100), colour VARCHAR(100))");
$db->exec("INSERT INTO fruit (name, colour) VALUES
                             ('apple', 'red'),
                             ('banana', 'yellow'),
                             ('orange', 'orange'),
                             ('kiwi', 'green')");
$sth = $db->prepare("SELECT name, colour FROM fruit");
$sth->execute();

/* Probar los estilos de PDOStatement::fetch */
echo "PDO::FETCH_ASSOC: ";
echo "Devuelve la siguiente línea como un array indexado por el nombre de la columna\n";
$result = $sth->fetch(PDO::FETCH_ASSOC);
var_dump($result);
echo "\n";

echo "PDO::FETCH_BOTH: ";
echo "Devuelve la siguiente línea como un array indexado por el nombre y el número de la columna\n";
$result = $sth->fetch(PDO::FETCH_BOTH);
var_dump($result);
echo "\n";

echo "PDO::FETCH_LAZY: ";
echo "Devuelve la siguiente línea como un objeto PDORow con los nombres de las columnas como propiedades\n";
$result = $sth->fetch(PDO::FETCH_LAZY);
var_dump($result);
echo "\n";

echo "PDO::FETCH_OBJ: ";
echo "Devuelve la siguiente línea como un objeto stdClass con los nombres de las columnas como propiedades\n";
$result = $sth->fetch(PDO::FETCH_OBJ);
var_dump($result);
echo "\n";
?>


   &example.outputs;


PDO::FETCH_ASSOC: Devuelve la siguiente línea como un array indexado por el nombre de la columna
array(2) {
  ["name"]=>
  string(5) "apple"
  ["colour"]=>
  string(3) "red"
}

PDO::FETCH_BOTH: Devuelve la siguiente línea como un array indexado por el nombre y el número de la columna
array(4) {
  ["name"]=>
  string(6) "banana"
  [0]=>
  string(6) "banana"
  ["colour"]=>
  string(6) "yellow"
  [1]=>
  string(6) "yellow"
}

PDO::FETCH_LAZY: Devuelve la siguiente línea como un objeto PDORow con los nombres de las columnas como propiedades
object(PDORow)#3 (3) {
  ["queryString"]=>
  string(30) "SELECT name, colour FROM fruit"
  ["name"]=>
  string(6) "orange"
  ["colour"]=>
  string(6) "orange"
}

PDO::FETCH_OBJ: Devuelve la siguiente línea como un objeto stdClass con los nombres de las columnas como propiedades
object(stdClass)#4 (2) {
  ["name"]=>
  string(4) "kiwi"
  ["colour"]=>
  string(5) "green"
}





   Recuperación de líneas con un cursor desplazable


<?php
function readDataForwards($dbh) {
    $sql = 'SELECT hand, won, bet FROM mynumbers ORDER BY BET';
    $stmt = $dbh->prepare($sql, array(PDO::ATTR_CURSOR => PDO::CURSOR_SCROLL));
    $stmt->execute();
    while ($row = $stmt->fetch(PDO::FETCH_NUM, PDO::FETCH_ORI_NEXT)) {
        $data = $row[0] . "\t" . $row[1] . "\t" . $row[2] . "\n";
        print $data;
    }
}
function readDataBackwards($dbh) {
    $sql = 'SELECT hand, won, bet FROM mynumbers ORDER BY bet';
    $stmt = $dbh->prepare($sql, array(PDO::ATTR_CURSOR => PDO::CURSOR_SCROLL));
    $stmt->execute();
    $row = $stmt->fetch(PDO::FETCH_NUM, PDO::FETCH_ORI_LAST);
    do {
        $data = $row[0] . "\t" . $row[1] . "\t" . $row[2] . "\n";
        print $data;
    } while ($row = $stmt->fetch(PDO::FETCH_NUM, PDO::FETCH_ORI_PRIOR));
}

print "Lectura hacia adelante:\n";
readDataForwards($conn);

print "Lectura hacia atrás:\n";
readDataBackwards($conn);
?>


   &example.outputs;


Lectura hacia adelante:
21    10    5
16    0     5
19    20    10

Lectura hacia atrás:
19    20    10
16    0     5
21    10    5





   Orden de construcción

    Cuando los objetos se recuperan mediante PDO::FETCH_CLASS,
    las propiedades del objeto se asignan primero y después se invoca el constructor
    de la clase. Sin embargo, cuando PDO::FETCH_PROPS_LATE también está especificado,
    este orden se invierte, es decir, primero se llama al constructor y
    después se asignan las propiedades.



<?php
class Person
{
    private $name;

    public function __construct()
    {
        $this->tell();
    }

    public function tell()
    {
        if (isset($this->name)) {
            echo "Soy {$this->name}.\n";
        } else {
            echo "Aún no tengo nombre.\n";
        }
    }
}

$sth = $dbh->query("SELECT * FROM people");
$sth->setFetchMode(PDO::FETCH_CLASS, 'Person');
$person = $sth->fetch();
$person->tell();
$sth->setFetchMode(PDO::FETCH_CLASS|PDO::FETCH_PROPS_LATE, 'Person');
$person = $sth->fetch();
$person->tell();
?>


   &example.outputs.similar;


Soy Alice.
Soy Alice.
Aún no tengo nombre.
Soy Bob.
